package server

const pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{if .Chapter}}{{.Root.Title}} · {{end}}{{.Saga.Manifest.Title}} · Review Saga</title>
<style>` + pageStyles + `</style><script src="/app.js" defer></script></head><body>
<header class="topbar"><div class="brand">Review Saga</div><div class="view-tabs" aria-label="Review workspace"><button class="view-tab active" data-view-tab="saga">Saga</button><button class="view-tab" data-view-tab="code">Code Diff</button>{{if .Manifest}}<button class="view-tab" data-view-tab="manifest">Manifest</button>{{end}}</div><div class="top-meta" hidden>{{len .Files}} files · {{.ReviewedFiles}} reviewed</div></header>
<div class="shell" data-shell><aside class="sidebar" id="changed-files-panel"><a class="sidebar-title" href="/">{{.Saga.Manifest.Title}}</a><div class="saga-side"><div class="side-label">Chapters</div>{{template "chapter-index" .Chapters}}{{if .Chapter}}<div class="side-label">On this page</div><nav>{{template "nav" .Root}}</nav>{{end}}</div><div class="code-side" hidden><div class="side-label">Changed files</div><div class="tree-tools"><input type="search" data-file-filter placeholder="Filter paths" aria-label="Filter changed files"><button type="button" class="tree-close" data-toggle-tree aria-label="Hide changed files">Hide</button></div><label class="tree-filter-check"><input type="checkbox" data-hide-reviewed> Hide reviewed files</label>{{if .Code}}<p class="tree-summary" data-tree-summary>{{.Code.Tree.ReviewedCount}} of {{.Code.Tree.FileCount}} reviewed · +{{.Code.Tree.Added}} −{{.Code.Tree.Deleted}}</p><div class="file-tree" role="tree" aria-label="Changed files">{{template "file-tree-nodes" .Code.Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p>{{end}}</div></aside>
<main class="content"><div class="view active" data-view="saga">{{if .Error}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Error}}</div>{{else if .Diagnostic}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Diagnostic}}</div>{{end}}{{if .Overview}}<header class="page-heading"><div class="eyebrow">Overview</div><h2>{{.Saga.Manifest.Title}}</h2></header>{{template "overview" .Root}}<section class="chapter-index"><h2>Continue with a chapter</h2>{{template "chapter-index" .Chapters}}</section>{{else}}<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Overview</a> <span aria-hidden="true">/</span> <span>{{.Root.Title}}</span></nav>{{template "section" .Root}}{{end}}</div>
<div class="view" data-view="code"><div class="code-toolbar" aria-label="Code review layout"><button type="button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true">Files</button><button type="button" data-layout="inline" aria-pressed="true">Inline</button><button type="button" data-layout="split" aria-pressed="false">Side by side</button><span class="spacer"></span><button type="button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true">Related saga</button></div><div class="code-workspace" data-code-workspace><div class="code-main"><div class="code-heading"><div><div class="side-label">Complete comparison</div><h2>Code Diff</h2></div><span class="metric">{{.ReviewedFiles}} / {{len .Files}} files reviewed</span></div>{{with .Code.SelectedFile}}{{template "file-diff" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .Code.SelectedFile}}<aside class="related-saga" id="related-saga-panel" aria-label="Related saga context"><div class="related-head"><h2>Related saga</h2><button type="button" data-toggle-related aria-label="Hide related saga">Hide</button></div>{{range .Code.RelatedSaga}}<section class="related-chapter"><a href="{{.Href}}">{{.Title}}</a>{{range .Fragments}}<a class="related-fragment" href="{{.Href}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}</section>{{else}}<p>{{.Code.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></main></div>
{{with .Manifest}}{{template "manifest-view" .}}{{end}}
<div class="annotation-toolbox" role="toolbar" aria-label="Annotation tools"><span class="tool-target" data-tool-target>No fragment selected</span><button type="button" data-tool="select" aria-pressed="true">Select</button><button type="button" data-tool="target" aria-pressed="false">Comment</button><button type="button" data-tool="text" aria-pressed="false">Highlight</button><button type="button" data-tool="rect" aria-pressed="false">Rectangle</button><button type="button" data-tool="draw" aria-pressed="false">Freehand</button><label class="annotation-color" title="Annotation color"><span class="sr-only">Annotation color</span><input type="color" data-annotation-color value="#d04832" aria-label="Annotation color"></label></div>
<dialog class="dialog decision-dialog" aria-labelledby="decision-title"><div class="dialog-head"><h2 id="decision-title">Record a decision</h2><button type="button" data-close-decision aria-label="Close decision dialog">Close</button></div><form class="dialog-form" method="post" action="/api/review"><input type="hidden" name="target"><textarea name="body" placeholder="Optional review note"></textarea><div class="decision-actions"><button name="state" value="approved">Approve</button><button class="danger" name="state" value="rejected">Request changes</button><button class="btn-subtle" name="state" value="closed">Close review</button></div></form></dialog>
<form class="dialog annotation-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="dialog-head"><h2>Comment on this fragment</h2><button type="button" data-close-annotation>Cancel</button></div><div class="dialog-form"><textarea name="body" placeholder="Start a review thread"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Create thread</button></div></form>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" aria-hidden="true" aria-label="Linked code"><div class="drawer-head"><strong>Linked code</strong><button type="button" data-close-drawer>Close</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" data-close-diff-compose>Cancel</button></div><div class="diff-compose-fields"><textarea name="body" placeholder="What should the author know?"></textarea><button type="submit">Add to review</button><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></div></form>
</body></html>{{end}}

{{define "manifest-view"}}<main class="manifest-view view" data-view="manifest"><div class="manifest-wrap"><header class="manifest-heading"><div><div class="eyebrow">Coverage audit</div><h1>Coverage Manifest</h1><p>Trace every source change to the Saga that explains it, or start from the Saga and inspect its exact code.</p></div><div class="manifest-verdict {{if .Complete}}complete{{else}}incomplete{{end}}" role="status"><span class="manifest-verdict-icon" aria-hidden="true">{{if .Complete}}✓{{else}}!{{end}}</span><span>{{if .Complete}}<strong>Everything is accounted for.</strong><small>Every source change has a live Saga mapping.</small>{{else if .Uncovered}}<strong>{{.Uncovered}} unmapped {{if eq .Uncovered 1}}change{{else}}changes{{end}}.</strong><small>These changes need a place in the Saga.</small>{{else}}<strong>Stale mappings found.</strong><small>Some Saga evidence no longer points to this comparison.</small>{{end}}</span></div></header>
<div class="manifest-metrics" aria-label="Coverage manifest summary"><span><strong>{{.Total}}</strong> source changes</span><span><strong>{{.MappingCount}}</strong> mappings</span><span><strong>{{len .Targets}}</strong> narrative targets</span><span><strong>{{.Overlapping}}</strong> shared mappings</span><span><strong>{{.Orphaned}}</strong> stale references</span></div>
<div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Manifest direction"><button type="button" data-manifest-mode="code" aria-pressed="true">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="false">Saga → Code</button></div><input type="search" data-manifest-filter placeholder="Filter files or narrative" aria-label="Filter coverage manifest"></div>
<section class="manifest-panel" data-manifest-panel="code"><div class="manifest-panel-head"><h2>Every changed file</h2><p>Expand a file to audit the narrative destination of each changed range.</p></div>{{range .Files}}{{template "manifest-file" .}}{{else}}<div class="manifest-empty">No source changes in this comparison.</div>{{end}}<p class="manifest-filter-empty" data-manifest-empty hidden>No files match this filter.</p></section>
<section class="manifest-panel" data-manifest-panel="saga" hidden><div class="manifest-panel-head"><h2>Every mapped Saga element</h2><p>Expand an element to inspect all source ranges it claims.</p></div>{{range .Targets}}{{template "manifest-target" .}}{{else}}<div class="manifest-empty">No Saga elements map to source changes yet.</div>{{end}}<p class="manifest-filter-empty" data-manifest-empty hidden>No narrative elements match this filter.</p></section>
{{if .Orphans}}<section class="manifest-orphans"><h2>Stale mappings</h2><p>These committed references do not match the current source comparison.</p>{{range .Orphans}}<div class="manifest-orphan"><span aria-hidden="true">!</span><div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open in Saga</a>{{end}}</div>{{end}}</section>{{end}}</div></main>{{end}}

{{define "manifest-file"}}<details class="manifest-group {{if .Uncovered}}has-gap{{end}}" data-manifest-search="{{.Path}}"><summary><span class="manifest-state" aria-label="{{if .Uncovered}}Has unmapped changes{{else}}Fully mapped{{end}}">{{if .Uncovered}}!{{else}}✓{{end}}</span><code>{{.Path}}</code><span class="manifest-group-stats">{{.AtomCount}} changes · +{{.Added}} −{{.Deleted}}{{if .Events}} · {{.Events}} events{{end}}{{if .Uncovered}} · <b>{{.Uncovered}} unmapped</b>{{end}}</span><span class="manifest-chevron" aria-hidden="true">›</span></summary><div class="manifest-rows">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></details>{{end}}

{{define "manifest-code-chunk"}}<div class="manifest-row {{if not .Covered}}unmapped{{end}}"><a class="manifest-range" href="{{.Href}}"><span>{{.Label}}</span><code>{{.Excerpt}}</code></a><div class="manifest-owners">{{range .Owners}}{{if .Href}}<a href="{{.Href}}"><span>{{.Kind}}</span><strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}</a>{{else}}<span class="manifest-owner-missing">{{.Title}}</span>{{end}}{{else}}<span class="manifest-gap">Needs a Saga mapping</span>{{end}}</div></div>{{end}}

{{define "manifest-target"}}<details class="manifest-group" data-manifest-search="{{.Title}} {{.Chapter}} {{.Kind}}"><summary><span class="manifest-kind">{{.Kind}}</span><span class="manifest-target-title"><strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}</span><span class="manifest-group-stats">{{.AtomCount}} mapped {{if eq .AtomCount 1}}change{{else}}changes{{end}}</span><span class="manifest-chevron" aria-hidden="true">›</span></summary><div class="manifest-rows manifest-target-rows">{{range .Chunks}}<a class="manifest-target-row" href="{{.Href}}"><code>{{.Path}}</code><span>{{.Label}}</span><small>{{.Excerpt}}</small></a>{{end}}<a class="manifest-open-saga" href="{{.Href}}">Open {{.Kind}} in Saga →</a></div></details>{{end}}

{{define "chapter-index"}}{{range .}}<a class="chapter-card {{if .Active}}active{{end}}" href="{{.URL}}" {{if .Active}}aria-current="page"{{end}}><span class="chapter-card-main"><span class="chapter-title">{{.Title}}</span><span class="chapter-summary">{{.Summary}}</span></span><span class="chapter-status">{{.Status}}</span><span class="chapter-arrow" aria-hidden="true">→</span></a>{{else}}<p>No chapters in this saga.</p>{{end}}{{end}}

{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details data-tree-folder {{if .Expanded}}open{{end}}><summary role="treeitem"><span aria-hidden="true">▸</span><span>{{.Name}}</span><span class="counts">{{.ReviewedCount}}/{{.FileCount}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" data-tree-file data-tree-path="{{.File.Path}}" data-reviewed="{{.File.Reviewed}}" class="{{if .File.Reviewed}}reviewed{{end}} {{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}"><span class="tree-state" aria-label="{{if .File.Reviewed}}Reviewed{{else}}Not reviewed{{end}}">{{if .File.Reviewed}}✓{{else}}○{{end}}</span><code>{{.Name}}</code><span class="counts">+{{.File.Added}} −{{.File.Deleted}}</span></a>{{end}}{{end}}{{end}}

{{define "nav"}}<a href="#{{.DOMID}}">{{.Title}}</a>{{if .ChildViews}}<div class="nav-child">{{range .ChildViews}}{{template "nav" .}}{{end}}</div>{{end}}{{end}}
{{define "diff-icon"}}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M8 3v12a4 4 0 0 0 4 4h4M5 6l3-3 3 3M13 16l3 3-3 3"/></svg>{{end}}
{{define "permalink"}}<button class="permalink" type="button" data-copy-link="#{{.}}" aria-label="Copy link"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.1.1l2-2a5 5 0 0 0-7.1-7.1l-1.1 1.1M14 11a5 5 0 0 0-7.1-.1l-2 2A5 5 0 0 0 12 20l1.1-1.1"/></svg></button>{{end}}
{{define "decision-button"}}<button class="icon-button" type="button" data-review-target="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-label="Review decisions for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}">⋯</button>{{end}}

{{define "overview"}}<section id="{{.DOMID}}">{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</section>{{end}}
{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div></div>{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}</section>{{end}}
{{define "diff-template"}}<template id="diffs-{{.DOMID}}">{{with .Attached}}{{template "attached-code" .}}{{end}}</template>{{end}}
{{define "attached-code"}}<div class="attached-code" data-attached-title="{{.Title}}"><header class="attached-code-summary"><div><strong>{{len .Files}} linked {{if eq (len .Files) 1}}file{{else}}files{{end}}</strong><span>{{.ChangeCount}} changed {{if eq .ChangeCount 1}}line or event{{else}}lines and events{{end}}</span></div><p>Start with what changed and why. Expand a file when you are ready to inspect its code.</p></header><div class="attached-file-list">{{range .Files}}<details class="attached-file"><summary><span class="attached-file-marker" aria-hidden="true">›</span><span class="attached-file-main"><code>{{.Path}}</code><span class="attached-file-note {{if .MissingSummary}}missing{{end}}">{{.Summary}}</span></span><span class="attached-file-counts">{{len .Changes}} changes · +{{.Added}} −{{.Deleted}}{{if .Events}} · {{.Events}} events{{end}}</span></summary><div class="attached-file-diff" data-file-path="{{.Path}}"><div class="attached-file-actions"><span>Linked ranges only</span><a href="{{.Href}}">Open full file in Code Diff →</a></div><div class="diff-column-head attached-columns" aria-hidden="true"><span>Old</span><span>New</span><span>±</span><span>Code</span><span>Actions</span></div><div class="diff-lines">{{range .Changes}}{{template "compact-diff-row" .}}{{end}}</div></div></details>{{end}}</div></div>{{end}}
{{define "landmark-affordance"}}<span class="landmark-affordance" data-landmark-affordance>{{template "permalink" .DOMID}}{{if .Changes}}<button type="button" class="btn-subtle diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open code related to {{.Label}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}</span>{{end}}
{{define "fragment"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head">{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<div class="fragment-actions">{{if .Changes}}<button type="button" class="btn-subtle diff-button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{if .LandmarkViews}}<details class="landmark-menu"><summary aria-label="Content landmarks">Links {{len .LandmarkViews}}</summary><div class="landmark-list">{{range .LandmarkViews}}<div><a href="#{{.DOMID}}">{{.Label}}</a>{{if .Changes}}<button type="button" class="btn-subtle diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open related code">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "permalink" .DOMID}}</div>{{end}}</div></details>{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div></div>{{range .LandmarkViews}}<span id="{{if eq .Selector.Type "heading"}}landmark-meta-{{end}}{{.DOMID}}" class="landmark-target" data-landmark-target data-landmark-anchor="{{.DOMID}}" data-landmark-type="{{.Selector.Type}}" data-element-id="{{.Selector.ElementID}}" data-heading-id="{{.Selector.HeadingID}}" data-exact="{{.Selector.Exact}}" data-prefix="{{.Selector.Prefix}}" data-suffix="{{.Selector.Suffix}}"><template data-landmark-affordance-template>{{template "landmark-affordance" .}}</template></span>{{if .Changes}}{{template "diff-template" .}}{{end}}{{end}}<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" data-fragment-frame sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open fragment</a>{{end}}{{range .LandmarkViews}}{{if .Region}}<div class="landmark-hotspot" data-landmark-visual="{{.DOMID}}" data-x="{{.Region.X}}" data-y="{{.Region.Y}}" data-width="{{.Region.Width}}" data-height="{{.Region.Height}}">{{template "landmark-affordance" .}}</div>{{end}}{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .Threads}}{{range .Anchor.Shapes}}{{$color := annotationColor .Color}}{{if eq .Type "rect"}}<rect class="annotation" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" x="{{coord .X}}" y="{{coord .Y}}" width="{{coord .Width}}" height="{{coord .Height}}"/>{{else if eq .Type "ellipse"}}<ellipse class="annotation" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" cx="{{coord .X}}" cy="{{coord .Y}}" rx="{{coord .Width}}" ry="{{coord .Height}}"/>{{else if eq .Type "line"}}<line class="annotation path" stroke="{{$color}}" x1="{{coord .X}}" y1="{{coord .Y}}" x2="{{coord .Width}}" y2="{{coord .Height}}"/>{{else if eq .Type "path"}}<polyline class="annotation path" stroke="{{$color}}" points="{{points .Points}}"/>{{end}}{{end}}{{end}}</svg></div>{{template "threads" .Threads}}{{range .LandmarkViews}}{{template "threads" .Threads}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "file-diff"}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}"><header class="file-head"><code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge" title="{{.ReviewerDetail}}">✓ Reviewed{{if .Reviewer}} by {{.Reviewer}}{{end}}</span>{{end}}<span class="counts">+{{.Added}} −{{.Deleted}}</span><details class="file-review-menu"><summary>{{if .Reviewed}}Reviewed{{else}}Review file{{end}}</summary><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><p>{{if .Reviewed}}Move this file back to the review queue.{{else}}Mark this file complete.{{end}}</p><button name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark reviewed{{else}}Mark reviewed{{end}}</button></form></details></header><div class="diff-surface" data-diff-surface data-layout="inline"><div class="diff-column-head" aria-hidden="true"><span class="inline-column">Old</span><span class="inline-column">New</span><span class="inline-column">±</span><span class="inline-column">Code</span><span class="inline-column">Actions</span><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines" data-diff-body>{{range .Lines}}{{template "diff-surface-row" .}}{{end}}</div><div class="diff-selection-toolbar" data-selection-toolbar role="toolbar" aria-label="Selected diff lines"><span data-selection-label></span><button type="button" data-selection-action="comment">Comment</button><button type="button" data-selection-action="suggestion">Suggest</button><button type="button" data-selection-clear>Clear</button></div></div></article>{{end}}

{{define "diff-surface-row"}}{{if eq .Kind "context"}}<div class="diff-row context" data-context-row role="row" aria-label="Unchanged line {{.NewLine}}"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true">·</span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event" role="row"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span>{{with .Atom}}<span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}{{end}}</div>{{else}}{{$atom := .Atom}}<div class="diff-row {{.Kind}} {{if $atom.Selected}}selected{{end}}" data-diff-row data-side="{{.Kind}}" data-line="{{if eq .Kind "old"}}{{.OldLine}}{{else}}{{.NewLine}}{{end}}" data-path="{{.Path}}" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" role="row" aria-label="{{if eq .Kind "old"}}Removed old line {{.OldLine}}{{else}}Added new line {{.NewLine}}{{end}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><button class="line-select" type="button" data-line-select aria-label="Select {{if eq .Kind "old"}}removed line {{.OldLine}}{{else}}added line {{.NewLine}}{{end}}">{{if .NewLine}}{{.NewLine}}{{end}}</button><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" $atom.Threads}}</div>{{end}}{{end}}
{{define "compact-diff-row"}}{{if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}</div>{{else}}<div class="diff-row {{.Side}}"><span class="line-no">{{if eq .Side "old"}}{{.Line}}{{end}}</span><span class="line-no">{{if eq .Side "new"}}{{.Line}}{{end}}</span><span class="sign">{{if eq .Side "new"}}+{{else}}−{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-diff-ref="{{.URI}}" data-target="{{.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" .Threads}}</div>{{end}}{{end}}
{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}
{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}{{$threadID := domID (printf "thread:%s" .ID)}}<article class="thread {{.State}} {{.Kind}}" id="{{$threadID}}"><div class="thread-meta"><span title="{{.AttributionDetail}}">{{.CreatedBy}}</span> · {{.CreatedAt.Format "2006-01-02 15:04 MST"}} · {{if .Kind}}{{.Kind}}{{else}}{{.Anchor.Type}}{{end}}{{if .StateAuthor}} · {{.State}} by <span title="{{.StateDetail}}">{{.StateAuthor}}</span>{{else}} · {{.State}}{{end}}{{template "permalink" $threadID}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-exact="{{.Anchor.Text.Exact}}" data-text-color="{{annotationColor .Anchor.Text.Color}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}{{$messageID := domID (printf "message:%s" $message.ID)}}<div class="message" id="{{$messageID}}"><div class="thread-meta" title="{{$message.AttributionDetail}}">{{$message.Author}} · {{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}{{template "permalink" $messageID}}</div>{{range index $thread.MessageViews $index}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input name="body" placeholder="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></form><form class="thread-state" method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><button name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
